    'on.mail_code_verify' => ["Merhaba {name},\n\nHesabını açmak için kodun: {code}\nKod 10 dakika geçerlidir.\n\n{shop}", "Hello {name},\n\nYour code to open your account: {code}\nIt is valid for 10 minutes.\n\n{shop}", "سلام {name}،\n\nکد باز کردن حساب: {code}\nاین کد ۱۰ دقیقه اعتبار دارد.\n\n{shop}", "Здравствуйте, {name}!\n\nКод для открытия аккаунта: {code}\nОн действует 10 минут.\n\n{shop}"],
